parameters.jsCode:
const body = $input.all()[0].json.body || $input.all()[0].json;

const required = ['client_id', 'poste', 'date_fin_collecte'];
const missing = required.filter(f => !body[f] || String(body[f]).trim() === '');

if (missing.length > 0) {
  return [{
    json: {
      valid: false,
      error: `Champs obligatoires manquants : ${missing.join(', ')}`,
      body: body
    }
  }];
}

return [{
  json: {
    valid: true,
    error: null,
    client_id:         parseInt(body.client_id),
    poste:             String(body.poste).trim(),
    lieu:              String(body.lieu || '').trim(),
    secteur:           String(body.secteur || '').trim(),
    mission:           String(body.mission || '').trim(),
    description_offre: String(body.description_offre || '').trim(),
    profil_requis:     String(body.profil_requis || '').trim(),
    date_fin_collecte: body.date_fin_collecte,
    nb_postes:         parseInt(body.nb_postes) || 1
  }
}];

const item = $input.all()[0].json;
const year = new Date().getFullYear();

return [{
  json: {
    ...item,
    year: year
  }
}];

const items = $input.all();
const seqRow = items[0].json;
const nextSeq = seqRow.next_seq || 1;

const validated = $node['Valider les champs'].json;
const year = new Date().getFullYear();

const seqPadded = String(nextSeq).padStart(3, '0');
const ref = `REF-${year}-${seqPadded}`;

const driveFolderName = `${ref} — ${validated.poste}`;

return [{
  json: {
    ref: ref,
    drive_folder_name: driveFolderName,
    client_id:         validated.client_id,
    poste:             validated.poste,
    lieu:              validated.lieu,
    secteur:           validated.secteur,
    mission:           validated.mission,
    description_offre: validated.description_offre,
    profil_requis:     validated.profil_requis,
    date_fin_collecte: validated.date_fin_collecte,
    nb_postes:         validated.nb_postes
  }
}];

const data = $node['Construire la REF finale'].json;
const drive = $input.all()[0].json;

const esc = (s) => String(s || '').replace(/'/g, "''");

const q = "INSERT INTO mandats (ref, client_id, poste, lieu, secteur, mission, description_offre, profil_requis, date_fin_collecte, nb_postes, drive_folder_id, statut, created_at) VALUES ('" + esc(data.ref) + "', " + parseInt(data.client_id) + ", '" + esc(data.poste) + "', '" + esc(data.lieu) + "', '" + esc(data.secteur) + "', '" + esc(data.mission) + "', '" + esc(data.description_offre) + "', '" + esc(data.profil_requis) + "', '" + esc(data.date_fin_collecte) + "'::date, " + (parseInt(data.nb_postes) || 1) + ", '" + esc(drive.id) + "', 'actif', NOW()) RETURNING id, ref, drive_folder_id, poste";

return [{
  json: {
    insert_query: q,
    ref: data.ref,
    poste: data.poste,
    drive_folder_id: drive.id
  }
}];

